SELECT  FROM report_goal
WHERE workspace_id = #{workspaceId}
ORDER BY period_start DESC, period_type, currency, owner_id, id

SELECT  FROM report_goal
WHERE workspace_id = #{workspaceId}
  AND metric = #{metric}
  AND period_type = #{periodType}
  AND period_start = #{periodStart}
ORDER BY currency, owner_id, id

mapper.update:
UPDATE report_goal
SET owner_id = #{ownerId}, metric = #{metric}, period_type = #{periodType},
    period_start = #{periodStart}, target_value = #{targetValue}, currency = #{currency}
WHERE workspace_id = #{workspaceId} AND id = #{id}
